import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector2 } = ctx.THREE;

  // Root container
  const root = new Group();

  // --------- Backdrop Gradient Plane (stage) ----------
  const BACKDROP_WIDTH = 7;
  const BACKDROP_HEIGHT = 6;
  const backdropGeom = new PlaneGeometry(BACKDROP_WIDTH, BACKDROP_HEIGHT);
  const gradientNode = mix(
    color(config.visual?.colors?.ink ?? '#16161d'),
    color(config.visual?.colors?.paper ?? '#e8ecf2'),
    uv().y
  );
  const backdropMat = new MeshBasicNodeMaterial({ color: gradientNode });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // --------- Textured Hero Plane ----------
  // Use image aspect ratio (provided by atlas rect if available)
  const imgWidth = 512;
  const imgHeight = 320;
  const aspect = imgHeight / imgWidth; // 0.625
  const HERO_WIDTH = BACKDROP_WIDTH * 0.9; // occupy ~90% of backdrop width
  const HERO_HEIGHT = HERO_WIDTH * aspect;

  const heroGeom = new PlaneGeometry(HERO_WIDTH, HERO_HEIGHT);
  const heroMat = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const heroMesh = new Mesh(heroGeom, heroMat);
  root.add(heroMesh);

  // Load texture asynchronously but synchronously inside the flow
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      heroMat.map = tex;
      heroMat.needsUpdate = true;
    });
  }

  // --------- Text Content ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 42,
      color: config.visual?.colors?.ink ?? '#16161d',
      align: 'center',
    });
    // Position text slightly above the hero plane
    txt.position.set(0, HERO_HEIGHT * 0.4, 0.01);
    root.add(txt);
  }

  // --------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const handler = ctx.primitives[primitive.name]?.(root, primitive.params);
      if (handler) primitiveHandles.push(handler);
    }
  }

  // --------- UserData (handlers & cleanup) ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry and material of backdrop
    backdropGeom.dispose();
    backdropMat.dispose();

    // Dispose hero
    heroGeom.dispose();
    heroMat.dispose();
    if (heroMat.map) heroMat.map.dispose();

    // Dispose any text objects (they manage their own resources)
    // Remove children
    while (root.children.length) {
      const child = root.children[0];
      root.remove(child);
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }

    // Kill any GSAP timelines (none created here, but guard)
    gsap.globalTimeline.clear();
  };

  return root;
}
